package com.example.mi_bolt_backend.admin.user;

import java.time.OffsetDateTime;
import java.util.UUID;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

/**
 * Admin account bound to the {@code /admin/**} API. The {@code id} is a UUID
 * generated by Hibernate ({@link GenerationType#UUID}); the first admin's id
 * is never the integer literal {@code 1}. {@code passwordHash} stores the
 * output of {@code PasswordEncoderFactories.createDelegatingPasswordEncoder()}
 * ({@code {bcrypt}} prefix plus the 60-character bcrypt string).
 *
 * <p>Schema lives in Liquibase changeset {@code 0007-admin-user.yaml}.
 */
@Entity
@Table(name = "admin_user")
public class AdminUser {

	@Id
	@GeneratedValue(strategy = GenerationType.UUID)
	@Column(nullable = false, updatable = false)
	private UUID id;

	@Column(nullable = false, length = 80, unique = true)
	private String username;

	@Column(name = "password_hash", nullable = false, length = 100)
	private String passwordHash;

	@Column(name = "created_at", nullable = false)
	private OffsetDateTime createdAt;

	protected AdminUser() {
		// JPA requires a no-arg constructor; field initialisation happens through the named constructor.
	}

	public AdminUser(String username, String passwordHash, OffsetDateTime createdAt) {
		this.username = username;
		this.passwordHash = passwordHash;
		this.createdAt = createdAt;
	}

	public UUID id() {
		return id;
	}

	public String username() {
		return username;
	}

	public String passwordHash() {
		return passwordHash;
	}

	public void setPasswordHash(String passwordHash) {
		this.passwordHash = passwordHash;
	}

	public OffsetDateTime createdAt() {
		return createdAt;
	}
}